#include "attachment_sample.h"
#include "track_attachment_types.h"
#include "object_render_types.h"
#include "sprite.h"
#include "transform_matrix.h"

float Sin(float angle);
float Cos(float angle);

typedef AttachmentSample PathTemplateSample;

static __forceinline void build_direct_strip_mesh(Path* path, char* texture)
{
    path->strip_mesh->RequestVertices(
        (path->width_cells + 1) * (path->segment_count + 1));
    path->strip_mesh->RequestFaceQuads(
        2 * path->width_cells * path->segment_count);

    Object* mesh = path->strip_mesh;
    Vector3* vertices = mesh->vertices;
    cRFaceQuad* facequads = mesh->facequads;
    int row;
    int column;

    row = 0;
    if (path->segment_count >= 0) {
        do {
            column = 0;
            if (path->width_cells >= 0) {
                do {
                    float lateral =
                        (float)column - (float)path->width_cells * 0.5f;
                    Vector3* vertex =
                        &vertices[column + row * (path->width_cells + 1)];
                    Vector3 lateral_offset(
                        lateral * path->primary_samples[row].transform.basis_right.x,
                        lateral * path->primary_samples[row].transform.basis_right.y,
                        lateral * path->primary_samples[row].transform.basis_right.z);
                    Vector3 generated_position =
                        path->primary_samples[row].transform.position + lateral_offset;
                    *vertex = generated_position;
                    ++column;
                } while (column <= path->width_cells);
            }
            ++row;
        } while (row <= path->segment_count);
    }

    for (row = 0; row < path->segment_count; ++row) {
        for (column = 0; column < path->width_cells; ++column) {
            int face_index = 0;
            float v0 = (float)(row % 8) * 0.125f;
            float v1 = (float)(row % 8 + 1) * 0.125f;
            float u0 = (float)column * 0.125f;
            float u1 = (float)(column + 1) * 0.125f;

            for (; face_index < 2; ++face_index) {
                int face_offset =
                    2 * column
                    + 2 * row * path->width_cells + face_index;
                if (face_index == 0) {
                    facequads[face_offset].vertex_0 = column
                        + row * ((unsigned short)path->width_cells + 1);
                    facequads[face_offset].vertex_1 = row
                        * ((unsigned short)path->width_cells + 1)
                        + column + 1;
                    facequads[face_offset].vertex_2 = (row + 1)
                        * ((unsigned short)path->width_cells + 1)
                        + column + 1;
                    facequads[face_offset].vertex_3 = column
                        + (row + 1)
                            * ((unsigned short)path->width_cells + 1);
                    if (!((column ^ row) & 1)) {
                        facequads[face_offset].texture_ref =
                            g_texture_refs.Add(texture, 0, 0);
                    } else {
                        facequads[face_offset].texture_ref =
                            g_texture_refs.Add(texture, 0, 0);
                    }
                } else {
                    facequads[face_offset].header_word = 4;
                    facequads[face_offset].vertex_0 = row
                        * ((unsigned short)path->width_cells + 1)
                        + column + 1;
                    facequads[face_offset].vertex_1 = column
                        + row * ((unsigned short)path->width_cells + 1);
                    facequads[face_offset].vertex_2 = column
                        + (row + 1)
                            * ((unsigned short)path->width_cells + 1);
                    facequads[face_offset].vertex_3 = (row + 1)
                        * ((unsigned short)path->width_cells + 1)
                        + column + 1;
                    if (!((column ^ row) & 1)) {
                        facequads[face_offset].texture_ref =
                            g_texture_refs.Add(texture, 0, 0);
                    } else {
                        facequads[face_offset].texture_ref =
                            g_texture_refs.Add(texture, 0, 0);
                    }
                }
                if (face_index == 0) {
                    facequads[face_offset].uv[0].u = u0;
                    facequads[face_offset].uv[0].v = v0;
                    facequads[face_offset].uv[1].u = u1;
                    facequads[face_offset].uv[1].v = v0;
                    facequads[face_offset].uv[2].u = u1;
                    facequads[face_offset].uv[2].v = v1;
                    facequads[face_offset].uv[3].u = u0;
                    facequads[face_offset].uv[3].v = v1;
                } else {
                    facequads[face_offset].uv[0].u = u1;
                    facequads[face_offset].uv[0].v = v0;
                    facequads[face_offset].uv[1].u = u0;
                    facequads[face_offset].uv[1].v = v0;
                    facequads[face_offset].uv[2].u = u0;
                    facequads[face_offset].uv[2].v = v1;
                    facequads[face_offset].uv[3].u = u1;
                    facequads[face_offset].uv[3].v = v1;
                }
            }
        }
    }
}

void cRPath::initialize_start_path_template_pair(
    float length,
    int width_cells_,
    bool side_exit,
    char* texture_a,
    char* texture_b,
    char* cap_texture)
{
    kind = PATH_TEMPLATE_KIND_START;
    is_mirrored_x = 0;
    side_exit_mode = 0;
    width_cells = width_cells_;

    int curve_segments = (int)(length * 3.1415927f);
    int last_segment_index = curve_segments + 15;
    width_or_scale = 1.0f;
    segment_count = last_segment_index + 1;
    segment_count_f = (float)last_segment_index;
    float curve_segments_f = (float)curve_segments;
    length = curve_segments_f * 0.31830987f;
    GetNodes();
    has_entry_mesh_transition = 0;
    segment_count = segment_count - 1;

    int i = 0;
    int lead_z_index = 0;
    do {
        primary_samples[i].center_x = 0.0f;
        primary_samples[i].rotation_scalar_98 = 0.0f;
        primary_samples[i].rotation_scalar_94 = 0.0f;
        primary_samples[i].special_scalar = 0.0f;
        primary_samples[i].lateral_scale = 1.0f;
        primary_samples[i].transform.Identity();
        primary_samples[i].transform.position.x = primary_samples[i].center_x;
        primary_samples[i].transform.position.y = length + length;
        float z = (float)lead_z_index;
        primary_samples[i].transform.position.z = z;
        primary_samples[i].delta_length = 1.0f;

        secondary_samples[i].transform.Identity();
        secondary_samples[i].transform.position.x = primary_samples[i].center_x;
        secondary_samples[i].transform.position.y =
            length + length + 0.49000001f;
        secondary_samples[i].transform.position.z = z;
        ++i;
        ++lead_z_index;
        secondary_samples[i - 1].delta_length = 1.0f;
    } while (i < 5);

    int tail_count = 11;
    int tail_z_index = curve_segments + 5;
    i = curve_segments + 5;
    do {
        primary_samples[i].center_x = 0.0f;
        primary_samples[i].rotation_scalar_98 = 0.0f;
        primary_samples[i].rotation_scalar_94 = 0.0f;
        primary_samples[i].special_scalar = 0.0f;
        primary_samples[i].lateral_scale = 1.0f;
        primary_samples[i].transform.Identity();
        primary_samples[i].transform.position.x = primary_samples[i].center_x;
        primary_samples[i].transform.position.y = 0.0f;
        primary_samples[i].transform.position.z = (float)tail_z_index;
        primary_samples[i].delta_length = 1.0f;

        secondary_samples[i].transform.Identity();
        secondary_samples[i].transform.position.x = primary_samples[i].center_x;
        secondary_samples[i].transform.position.y = 0.49000001f;
        secondary_samples[i].transform.position.z =
            primary_samples[i].transform.position.z;
        secondary_samples[i].delta_length = 1.0f;
        ++i;
        ++tail_z_index;
        --tail_count;
    } while (tail_count != 0);

    int curve_index = 0;
    if (curve_index < curve_segments) {
        i = 5;
        do {
            primary_samples[i].center_x = 0.0f;
            primary_samples[i].rotation_scalar_98 = 0.0f;
            primary_samples[i].rotation_scalar_94 = 0.0f;
            primary_samples[i].special_scalar = 0.0f;
            primary_samples[i].lateral_scale = 1.0f;
            primary_samples[i].transform.Identity();
            primary_samples[i].transform.position.x = primary_samples[i].center_x;
            float z = (float)(curve_index + 5);
            primary_samples[i].transform.position.z = z;
            float angle =
                (float)curve_index * 3.1415927f / curve_segments_f;
            primary_samples[i].transform.position.y =
                (Cos(angle) + 1.0f) * length;

            secondary_samples[i].transform.Identity();
            secondary_samples[i].transform.position.x = primary_samples[i].center_x;
            secondary_samples[i].transform.position.z = z;
            secondary_samples[i].transform.position.y =
                primary_samples[i].transform.position.y + 0.49000001f;
            if (curve_index != 0) {
                primary_samples[i - 1].transform.basis_right =
                    Vector3(1.0f, 0.0f, 0.0f);
                primary_samples[i - 1].transform.basis_forward =
                    primary_samples[i].transform.position -
                    primary_samples[i - 1].transform.position;
                primary_samples[i - 1]
                    .transform.basis_forward.Normalize();
                primary_samples[i - 1].transform.basis_up.Cross(
                    primary_samples[i - 1].transform.basis_forward,
                    primary_samples[i - 1].transform.basis_right);

                secondary_samples[i - 1].transform.basis_right =
                    Vector3(1.0f, 0.0f, 0.0f);
                secondary_samples[i - 1].transform.basis_forward =
                    secondary_samples[i].transform.position -
                    secondary_samples[i - 1].transform.position;
                secondary_samples[i - 1]
                    .transform.basis_forward.Normalize();
                secondary_samples[i - 1].transform.basis_up.Cross(
                    secondary_samples[i - 1].transform.basis_forward,
                    secondary_samples[i - 1].transform.basis_right);
            } else {
                PathTemplateSample* primary_previous =
                    &primary_samples[i - 1];
                primary_previous->transform.RotIdentity();
                PathTemplateSample* secondary_previous =
                    &secondary_samples[i - 1];
                secondary_previous->transform.RotIdentity();
            }
            ++curve_index;
            ++i;
        } while (curve_index < curve_segments);
    }

    int delta_index = 0;
    if (segment_count > 0) {
        do {
            primary_samples[delta_index].delta_dir_to_next =
                primary_samples[delta_index + 1].transform.position -
                primary_samples[delta_index].transform.position;
            primary_samples[delta_index].delta_length =
                primary_samples[delta_index].delta_dir_to_next.Normalize();

            secondary_samples[delta_index].delta_dir_to_next =
                secondary_samples[delta_index + 1].transform.position -
                secondary_samples[delta_index].transform.position;
            secondary_samples[delta_index].delta_length =
                secondary_samples[delta_index].delta_dir_to_next.Normalize();

            ++delta_index;
        } while (delta_index < segment_count);
    }
    build_direct_strip_mesh(this, texture_a);
    CalcLengthZ();
    (void)side_exit;
    (void)texture_b;
    (void)cap_texture;
}

