static __forceinline void build_start_curve(Path *path, int curve_segments, float curve_segments_f, float length)
{
    int i;
    int curve_index;
    if (curve_segments > 0) {
    for (curve_index = 0, i = 5; curve_index < curve_segments; ++curve_index, ++i) {
            path->primary_samples[i].center_x = 0.0f;
            path->primary_samples[i].rotation_scalar_98 = 0.0f;
            path->primary_samples[i].rotation_scalar_94 = 0.0f;
            path->primary_samples[i].special_scalar = 0.0f;
            path->primary_samples[i].lateral_scale = 1.0f;
            path->primary_samples[i].transform.Identity();
            path->primary_samples[i].transform.position.x = path->primary_samples[i].center_x;
            float z = (float)(curve_index + 5);
            path->primary_samples[i].transform.position.z = z;
            float angle =
                (float)curve_index * 3.1415927f / curve_segments_f;
            path->primary_samples[i].transform.position.y =
                (Cos(angle) + 1.0f) * length;

            path->secondary_samples[i].transform.Identity();
            path->secondary_samples[i].transform.position.x = path->primary_samples[i].center_x;
            path->secondary_samples[i].transform.position.z = z;
            path->secondary_samples[i].transform.position.y =
                path->primary_samples[i].transform.position.y + 0.49000001f;
            if (i * (int)sizeof(PathTemplateSample) > 5 * (int)sizeof(PathTemplateSample)) {
                path->primary_samples[i - 1].transform.basis_right =
                    Vector3(1.0f, 0.0f, 0.0f);
                path->primary_samples[i - 1].transform.basis_forward =
                    path->primary_samples[i].transform.position -
                    path->primary_samples[i - 1].transform.position;
                path->primary_samples[i - 1]
                    .transform.basis_forward.Normalize();
                path->primary_samples[i - 1].transform.basis_up.Cross(
                    path->primary_samples[i - 1].transform.basis_forward,
                    path->primary_samples[i - 1].transform.basis_right);

                path->secondary_samples[i - 1].transform.basis_right =
                    Vector3(1.0f, 0.0f, 0.0f);
                path->secondary_samples[i - 1].transform.basis_forward =
                    path->secondary_samples[i].transform.position -
                    path->secondary_samples[i - 1].transform.position;
                path->secondary_samples[i - 1]
                    .transform.basis_forward.Normalize();
                path->secondary_samples[i - 1].transform.basis_up.Cross(
                    path->secondary_samples[i - 1].transform.basis_forward,
                    path->secondary_samples[i - 1].transform.basis_right);
            } else {
                PathTemplateSample* primary_previous =
                    &path->primary_samples[i - 1];
                primary_previous->transform.RotIdentity();
                PathTemplateSample* secondary_previous =
                    &path->secondary_samples[i - 1];
                secondary_previous->transform.RotIdentity();
            }
    }
    }

}

