        ((PathAttachmentSample*)((char*)primary_samples + departure_sample_offset))
            ->rotation_scalar_98 = 0.0f;
        ((PathAttachmentSample*)((char*)primary_samples + departure_sample_offset))
            ->rotation_scalar_94 = 0.0f;
        ((PathAttachmentSample*)((char*)primary_samples + departure_sample_offset))
            ->special_scalar = 0.0f;
        ((PathAttachmentSample*)((char*)primary_samples + departure_sample_offset))
            ->lateral_scale = 1.0f;
        ((PathAttachmentSample*)((char*)primary_samples + departure_sample_offset))
                ->transform.Identity();
